/**
 * `launchpad.json`, the content of a launchpad (decision D37), resolved against the applications
 * generated by `rapt build`: their service paths, entity sets, roles and claims. The counterpart
 * of the content of the SAP Fiori launchpad (catalogs, groups, tiles, target mappings), in one
 * file versioned with the sources.
 *
 * ```json
 * {
 *   "title": "Travel agency",
 *   "apps": [{ "id": "travel", "build": "../build/travel", "url": "http://localhost:8080/" }],
 *   "groups": [{
 *     "title": "Travels",
 *     "tiles": [{ "title": "Manage Travels", "app": "travel", "intent": "Travel-manage",
 *                 "icon": "sap-icon://flight", "count": "Travel", "roles": ["travel_agent"] }]
 *   }]
 * }
 * ```
 */

import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { authorizationClaims, LAUNCHPAD_RESERVED_PATHS, type LaunchpadApp, type LaunchpadGroup, type LaunchpadModel, type LaunchpadTile, type Model } from "@rap-transpiler/model";
import type { Diagnostics, Location } from "../diagnostics.js";

interface AppSource {
  id?: unknown;
  title?: unknown;
  /** The folder generated by `rapt build`, relative to launchpad.json. */
  build?: unknown;
  url?: unknown;
  servicePaths?: unknown;
}

interface TileSource {
  id?: unknown;
  title?: unknown;
  subtitle?: unknown;
  info?: unknown;
  icon?: unknown;
  intent?: unknown;
  app?: unknown;
  url?: unknown;
  count?: unknown;
  roles?: unknown;
}

/** What the launchpad knows of a generated application. */
export interface ResolvedApp extends LaunchpadApp {
  /** The generated folder, when given. */
  build?: string;
  model?: Model;
}

export interface LaunchpadResolution {
  model: LaunchpadModel;
  apps: ResolvedApp[];
}

const ID = /^[a-z][a-z0-9-]*$/;
const INTENT = /^[A-Za-z][A-Za-z0-9_]*-[A-Za-z][A-Za-z0-9_]*$/;

const text = (value: unknown): string | undefined => (typeof value === "string" && value.trim() !== "" ? value.trim() : undefined);
const slug = (value: string): string => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "tile";

/** The title of a generated application: its UI (`sap.app.title`), else its service. */
function appTitle(dir: string, model: Model): string {
  try {
    const manifest = JSON.parse(readFileSync(path.join(dir, "ui", "manifest.json"), "utf8")) as { "sap.app"?: { title?: string } };
    const title = manifest["sap.app"]?.title;
    if (typeof title === "string" && title !== "") {
      return title;
    }
  } catch {
    // an application without UI
  }
  return model.service.name;
}

function resolveApp(source: AppSource, base: string, at: Location, diagnostics: Diagnostics): ResolvedApp | undefined {
  const id = text(source.id);
  if (id === undefined || !ID.test(id)) {
    diagnostics.error("LPD001", `an application needs an id of lower-case letters, digits and "-" (found ${JSON.stringify(source.id)})`, at);
    return undefined;
  }
  const url = text(source.url);
  if (url === undefined || !/^https?:\/\//.test(url)) {
    diagnostics.error("LPD001", `the application ${id} needs the url where the launchpad reaches it (http://host:port/)`, at);
    return undefined;
  }
  const app: ResolvedApp = { id, title: text(source.title) ?? id, url: url.endsWith("/") ? url : `${url}/`, servicePaths: [] };
  const build = text(source.build);
  if (build !== undefined) {
    const dir = path.resolve(base, build);
    const file = path.join(dir, "model", "model.json");
    if (!existsSync(file)) {
      diagnostics.error("LPD003", `the application ${id}: ${build} is not a folder generated by rapt build (no model/model.json)`, at);
    } else {
      try {
        const model = JSON.parse(readFileSync(file, "utf8")) as Model;
        app.build = dir;
        app.model = model;
        app.servicePaths = [model.service.path];
        if (text(source.title) === undefined) {
          app.title = appTitle(dir, model);
        }
      } catch (error) {
        diagnostics.error("LPD003", `the application ${id}: ${file} cannot be read (${(error as Error).message})`, at);
      }
    }
  }
  if (source.servicePaths !== undefined) {
    if (!Array.isArray(source.servicePaths) || source.servicePaths.some((p) => typeof p !== "string" || !p.startsWith("/"))) {
      diagnostics.error("LPD005", `the application ${id}: servicePaths is a list of absolute paths (/sap/opu/odata4/…/)`, at);
    } else {
      app.servicePaths = [...new Set([...app.servicePaths, ...(source.servicePaths as string[]).map((p) => (p.endsWith("/") ? p : `${p}/`))])];
    }
  }
  if (app.servicePaths.length === 0) {
    diagnostics.warning("LPD003", `the application ${id} has neither build nor servicePaths: its services are not forwarded, its UI cannot read them through the launchpad`, at);
  }
  return app;
}

/** `count`: an entity set of the service of the application, or `{ "entitySet": …, "filter": … }`. */
function countPath(tile: TileSource, app: ResolvedApp | undefined, name: string, at: Location, diagnostics: Diagnostics): string | undefined {
  if (tile.count === undefined) {
    return undefined;
  }
  const spec = typeof tile.count === "string" ? { entitySet: tile.count } : (tile.count as { entitySet?: unknown; filter?: unknown } | null);
  const entitySet = text(spec?.entitySet);
  if (entitySet === undefined) {
    diagnostics.error("LPD006", `tile ${name}: count is an entity set, or { "entitySet": …, "filter": … }`, at);
    return undefined;
  }
  if (app === undefined || app.servicePaths.length === 0) {
    diagnostics.error("LPD006", `tile ${name}: a count needs the app of the tile, whose services the launchpad knows`, at);
    return undefined;
  }
  const servicePath = app.servicePaths[0] as string;
  if (app.model !== undefined && !app.model.service.entitySets.some((s) => s.name === entitySet)) {
    diagnostics.error("LPD006", `tile ${name}: the service of ${app.id} has no entity set ${entitySet} (${app.model.service.entitySets.map((s) => s.name).join(", ")})`, at);
    return undefined;
  }
  const filter = text(spec?.filter);
  return `${servicePath}${entitySet}/$count${filter === undefined ? "" : `?$filter=${encodeURIComponent(filter)}`}`;
}

export function resolveLaunchpad(file: string, diagnostics: Diagnostics): LaunchpadResolution | undefined {
  const at: Location = { file };
  let source: { title?: unknown; apps?: unknown; groups?: unknown; claims?: unknown };
  try {
    source = JSON.parse(readFileSync(file, "utf8")) as typeof source;
  } catch (error) {
    diagnostics.error("LPD001", `launchpad.json cannot be read: ${(error as Error).message}`, at);
    return undefined;
  }
  if (source === null || typeof source !== "object" || !Array.isArray(source.groups)) {
    diagnostics.error("LPD001", "launchpad.json needs groups: a list of { title, tiles }", at);
    return undefined;
  }
  const base = path.dirname(path.resolve(file));

  const apps: ResolvedApp[] = [];
  for (const entry of Array.isArray(source.apps) ? (source.apps as AppSource[]) : []) {
    const app = resolveApp(entry ?? {}, base, at, diagnostics);
    if (app === undefined) {
      continue;
    }
    if (apps.some((a) => a.id === app.id)) {
      diagnostics.error("LPD001", `two applications have the id ${app.id}`, at);
      continue;
    }
    for (const servicePath of app.servicePaths) {
      const reserved = LAUNCHPAD_RESERVED_PATHS.find((p) => servicePath === `${p}/` || servicePath.startsWith(`${p}/`));
      if (reserved !== undefined) {
        diagnostics.error("LPD005", `the application ${app.id}: the service path ${servicePath} is below ${reserved}, a path of the launchpad`, at);
      }
      const other = apps.find((a) => a.servicePaths.some((p) => p.startsWith(servicePath) || servicePath.startsWith(p)));
      if (other !== undefined) {
        diagnostics.error("LPD005", `the applications ${other.id} and ${app.id} both serve ${servicePath}: the launchpad cannot tell their requests apart`, at);
      }
    }
    apps.push(app);
  }

  // the roles of the applications (rapt/authorizations.json), for the realm and the checks of the tiles
  const roles = new Map<string, { name: string; description?: string }>();
  for (const app of apps) {
    for (const role of app.model?.authorizations?.roles ?? []) {
      if (!roles.has(role.name)) {
        roles.set(role.name, role.description === undefined ? { name: role.name } : { name: role.name, description: role.description });
      }
    }
  }
  const knownRoles = new Set([...roles.keys(), "rapt_user"]);
  // without roles in the applications, the roles of the tiles are those of the identity provider only
  const checkRoles = roles.size > 0;

  const ids = new Set<string>();
  const groups: LaunchpadGroup[] = [];
  for (const [g, group] of (source.groups as Array<{ title?: unknown; tiles?: unknown }>).entries()) {
    const title = text(group?.title);
    if (title === undefined || !Array.isArray(group.tiles)) {
      diagnostics.error("LPD001", `group ${g + 1} needs a title and tiles (a list)`, at);
      continue;
    }
    const tiles: LaunchpadTile[] = [];
    for (const [t, tile] of (group.tiles as TileSource[]).entries()) {
      const appId = text(tile?.app);
      const app = appId === undefined ? undefined : apps.find((a) => a.id === appId);
      const name = text(tile?.title) ?? text(tile?.intent) ?? `${t + 1} of ${title}`;
      if (appId !== undefined && app === undefined) {
        diagnostics.error("LPD002", `tile ${name}: no application ${appId} in apps`, at);
        continue;
      }
      const url = text(tile.url);
      if ((app === undefined) === (url === undefined)) {
        diagnostics.error("LPD002", `tile ${name}: give either app (an application of the launchpad) or url`, at);
        continue;
      }
      const tileTitle = text(tile.title) ?? app?.title;
      if (tileTitle === undefined) {
        diagnostics.error("LPD001", `tile ${t + 1} of ${title} needs a title`, at);
        continue;
      }
      const intent = text(tile.intent);
      if (tile.intent !== undefined && (intent === undefined || !INTENT.test(intent))) {
        diagnostics.error("LPD004", `tile ${name}: the intent is SemanticObject-action (found ${JSON.stringify(tile.intent)})`, at);
        continue;
      }
      if (tile.roles !== undefined && (!Array.isArray(tile.roles) || tile.roles.some((r) => typeof r !== "string" || r === ""))) {
        diagnostics.error("LPD001", `tile ${name}: roles is a list of role names`, at);
        continue;
      }
      const tileRoles = (tile.roles as string[] | undefined) ?? [];
      for (const role of tileRoles) {
        if (checkRoles && !knownRoles.has(role)) {
          diagnostics.warning("LPD007", `tile ${name}: the role ${role} is in no rapt/authorizations.json of the applications; the identity provider must still give it`, at);
        }
        if (!roles.has(role)) {
          roles.set(role, { name: role });
        }
      }
      let id = slug(text(tile.id) ?? intent ?? tileTitle);
      for (let n = 2; ids.has(id); n++) {
        id = `${slug(text(tile.id) ?? intent ?? tileTitle)}-${n}`;
      }
      ids.add(id);
      const target = app === undefined ? (url as string) : `/apps/${app.id}/ui/index.html`;
      const resolved: LaunchpadTile = { id, title: tileTitle, target, external: !target.startsWith("/"), roles: tileRoles };
      const optional: Array<["subtitle" | "info" | "icon", unknown]> = [
        ["subtitle", tile.subtitle],
        ["info", tile.info],
        ["icon", tile.icon],
      ];
      for (const [key, value] of optional) {
        const v = text(value);
        if (v !== undefined) {
          resolved[key] = v;
        }
      }
      if (intent !== undefined) resolved.intent = intent;
      if (app !== undefined) resolved.app = app.id;
      const count = countPath(tile, app, name, at, diagnostics);
      if (count !== undefined) resolved.count = count;
      tiles.push(resolved);
    }
    groups.push({ title, tiles });
  }

  const extra = Array.isArray(source.claims) ? source.claims.filter((c): c is string => typeof c === "string" && c !== "") : [];
  const claims = [...new Set([...apps.flatMap((a) => authorizationClaims(a.model?.authorizations)), ...extra])].sort();
  const model: LaunchpadModel = {
    title: text(source.title) ?? "Launchpad",
    apps: apps.map((a) => ({ id: a.id, title: a.title, url: a.url, servicePaths: a.servicePaths })),
    groups,
    claims,
    roles: [...roles.values()],
  };
  return { model, apps };
}
